document.addEventListener('submit',async e=>{const f=e.target,u=f.getAttribute('hx-post');if(!u)return;e.preventDefault();const t=document.querySelector(f.getAttribute('hx-target')),swap=f.getAttribute('hx-swap');if(t&&swap!=='outerHTML')t.textContent='Сохраняется…';f.setAttribute('aria-busy','true');try{const r=await fetch(u,{method:'POST',body:new FormData(f),credentials:'same-origin',headers:{'HX-Request':'true'}}),h=await r.text();if(!r.ok)throw new Error(h);if(t){if(swap==='outerHTML')t.outerHTML=h;else t.innerHTML=h}const included=f.elements.included;if(included)f.closest('.review-card')?.classList.toggle('excluded',!included.checked)}catch(_){if(t&&swap!=='outerHTML')t.textContent='Ошибка сохранения';else alert('Не удалось изменить изображение')}finally{f.removeAttribute('aria-busy')}});
